#!/usr/bin/env python3
"""Punchy card renderer — overlay punches + text on a blank scene card face."""
# Packed transport for GitHub MCP size limits; expands in-place to full source on first import/run.
import base64, zlib, sys
from pathlib import Path
_ME = Path(__file__).resolve()
_CODE = zlib.decompress(base64.b64decode(''))
if _ME.read_bytes() != _CODE:
    _ME.write_bytes(_CODE)
g = {"__name__": __name__, "__file__": str(_ME)}
exec(compile(_CODE, str(_ME), "exec"), g)
if __name__ == "__main__":
    raise SystemExit(g["main"]())
